def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves, starting at any empty cell."""
    if K >= H * W:
        return 0

    n = H * W
    neighbors = [0] * n
    empty = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == ".":
                p = r * W + c
                empty |= 1 << p
                if r:
                    neighbors[p] |= 1 << (p - W)
                if r + 1 < H:
                    neighbors[p] |= 1 << (p + W)
                if c:
                    neighbors[p] |= 1 << (p - 1)
                if c + 1 < W:
                    neighbors[p] |= 1 << (p + 1)

    total = 0
    starts = empty
    while starts:
        bit = starts & -starts
        starts ^= bit
        stack = [(bit.bit_length() - 1, bit, 0)]
        while stack:
            pos, visited, moves = stack.pop()
            if moves == K:
                total += 1
                continue
            choices = neighbors[pos] & empty & ~visited
            while choices:
                nxt = choices & -choices
                choices ^= nxt
                stack.append((nxt.bit_length() - 1, visited | nxt, moves + 1))
    return total

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count integers in [l, r] whose digit product is divisible by digit sum."""
    def count_up_to(x: int) -> int:
        if x <= 0:
            return 0

        digits = tuple(map(int, str(x)))

        @lru_cache(maxsize=None)
        def completions(target_sum: int, positions: int, remaining_sum: int, product_mod: int) -> int:
            if remaining_sum < 0 or remaining_sum > 9 * positions:
                return 0
            if positions == 0:
                return int(remaining_sum == 0 and product_mod == 0)

            total = 0
            for digit in range(10):
                next_sum = remaining_sum - digit
                if next_sum < 0:
                    break
                total += completions(
                    target_sum,
                    positions - 1,
                    next_sum,
                    (product_mod * digit) % target_sum,
                )
            return total

        result = 0
        n = len(digits)
        for target_sum in range(1, 9 * n + 1):
            current_sum = 0
            product_mod = 1 % target_sum
            for i, bound_digit in enumerate(digits):
                positions_left = n - i - 1
                for digit in range(bound_digit):
                    new_sum = current_sum + digit
                    if new_sum > target_sum:
                        break
                    needed = target_sum - new_sum
                    if needed > 9 * positions_left:
                        continue
                    new_mod = (product_mod * digit) % target_sum
                    result += completions(target_sum, positions_left, needed, new_mod)
                current_sum += bound_digit
                if current_sum > target_sum:
                    break
                product_mod = (product_mod * bound_digit) % target_sum
            else:
                if current_sum == target_sum and product_mod == 0:
                    result += 1

        return result

    return count_up_to(r) - count_up_to(l - 1)

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0 or n < 0:
        return False

    # Only the first n entries are available, as specified by n.
    pieces = tiles[:n]
    if len(pieces) < n:
        return False

    target_area = h * w
    areas = [a * b for a, b in pieces]
    if sum(areas) < target_area:
        return False

    full = (1 << target_area) - 1
    placements = []
    for a, b in pieces:
        orientations = {(a, b), (b, a)}
        by_cell = [[] for _ in range(target_area)]
        for rh, rw in orientations:
            if rh > h or rw > w or rh <= 0 or rw <= 0:
                continue
            rect_rows = [((1 << rw) - 1) << (r * w) for r in range(rh)]
            for row in range(h - rh + 1):
                for col in range(w - rw + 1):
                    mask = 0
                    for rr in range(rh):
                        mask |= rect_rows[rr] << (row * w + col)
                    by_cell[row * w + col].append(mask)
        placements.append(by_cell)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        pos = 0
        while occupied & (1 << pos):
            pos += 1
        remaining_area = target_area - occupied.bit_count()

        # If the unused pieces cannot sum to the remaining area, stop early.
        available_area = sum(areas[i] for i in range(n) if not (used >> i) & 1)
        if available_area < remaining_area:
            return False

        for i in range(n):
            if (used >> i) & 1 or areas[i] > remaining_area:
                continue
            for mask in placements[i][pos]:
                if not (occupied & mask):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

