MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid with H rows and W columns of '1', '2', '3', and '?',
    count replacements of '?' such that edge-sharing cells differ.

    Return the count modulo 998244353.
    """
    # Use the shorter dimension as the transfer width.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    full = (1 << W) - 1
    # For each position, a bit mask of the permitted colors (bits 0..2).
    allowed = []
    for row in grid:
        masks = []
        for ch in row:
            if ch == '?':
                masks.append(7)
            elif ch in '123':
                masks.append(1 << (ord(ch) - ord('1')))
            else:
                return 0
        allowed.append(masks)

    # All horizontally proper row assignments, encoded in base 3.
    states = []
    digits = []
    masks_by_state = []
    row_mask_sets = []
    # This recursion also avoids considering assignments that violate fixed cells.
    def initial_rows(pos, prev, code, ds, masks):
        if pos == W:
            states.append(code)
            digits.append(ds)
            masks_by_state.append(masks)
            return
        for color in range(3):
            if allowed[0][pos] & (1 << color) and color != prev:
                initial_rows(pos + 1, color, code * 3 + color, ds + (color,), masks + (1 << color,))

    initial_rows(0, -1, 0, (), ())
    if not states:
        return 0

    dp = [1] * len(states)
    for r in range(1, H):
        index = {code: i for i, code in enumerate(states)}
        ndp = [0] * len(states)
        # Generate each next row from each previous row. Only color choices
        # differing from the cell above and the cell to the left are visited.
        for i, value in enumerate(dp):
            if not value:
                continue
            old = digits[i]
            chosen = [0] * W

            def extend(pos, code):
                if pos == W:
                    j = index.get(code)
                    if j is not None:
                        ndp[j] = (ndp[j] + value) % MOD
                    return
                forbidden = old[pos]
                for color in range(3):
                    if (allowed[r][pos] & (1 << color)
                            and color != forbidden
                            and (pos == 0 or color != chosen[pos - 1])):
                        chosen[pos] = color
                        extend(pos + 1, code * 3 + color)

            extend(0, 0)
        dp = ndp

    return sum(dp) % MOD

