from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to monitor each section with the available sensors."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    if l1 <= 0 or l2 <= 0:
        return -1

    # A section is covered with sensors of one type; the counts across sections
    # share the two global inventory limits.
    states = {(0, 0): 0}
    for length in sections[:n]:
        a = (length + l1 - 1) // l1
        b = (length + l2 - 1) // l2
        nxt = {}
        for (used1, used2), cost in states.items():
            if used1 + a <= k1:
                key = (used1 + a, used2)
                value = cost + a * c1
                if value < nxt.get(key, float("inf")):
                    nxt[key] = value
            if used2 + b <= k2:
                key = (used1, used2 + b)
                value = cost + b * c2
                if value < nxt.get(key, float("inf")):
                    nxt[key] = value
        if not nxt:
            return -1

        # Discard states that use no fewer sensors of either type and cost no
        # less than another state. This keeps the assignment frontier compact.
        ordered = sorted((x, y, v) for (x, y), v in nxt.items())
        frontier = {}
        best_by_y = []
        for x, y, value in ordered:
            if any(py <= y and pv <= value for py, pv in best_by_y):
                continue
            frontier[(x, y)] = value
            best_by_y.append((y, value))
            best_by_y = [(py, pv) for py, pv in best_by_y if not (y <= py and value <= pv and (y, value) != (py, pv))]
        states = frontier

    return min(states.values(), default=-1)

