from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to monitor all sections within sensor inventory limits."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    if l1 <= 0 or l2 <= 0:
        return -1

    # Track the least cost for each pair of total sensor counts. For a fixed
    # count of type 1 on one section, only the minimum sufficient type 2 count
    # can be useful because costs are nonnegative.
    states = {(0, 0): 0}
    for length in sections[:n]:
        max_x = min((length + l1 - 1) // l1, k1)
        options = []
        for x in range(max_x + 1):
            remaining = max(0, length - x * l1)
            y = (remaining + l2 - 1) // l2
            if y <= k2:
                options.append((x, y, x * c1 + y * c2))
        if not options:
            return -1

        nxt = {}
        for (used1, used2), cost in states.items():
            for x, y, added in options:
                total1, total2 = used1 + x, used2 + y
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    value = cost + added
                    if value < nxt.get(key, float("inf")):
                        nxt[key] = value
        if not nxt:
            return -1
        states = nxt
    return min(states.values(), default=-1)

