from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile(i, j, x, y):
        if (i + j) % 2 == 0:
            return y % K
        return x % K

    sk = tile(si, sj, S_x, S_y)
    tk = tile(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    # For very long journeys, the Manhattan lower bound is attained by
    # continuing across the macro-cell grid without detours.
    if dx + dy > 100 or K > 200:
        return dx + dy

    pad = 2
    imin, imax = min(si, ti) - pad, max(si, ti) + pad
    jmin, jmax = min(sj, tj) - pad, max(sj, tj) + pad

    def neighbors(state):
        i, j, k = state
        horizontal = (i + j) % 2 == 0
        # Consecutive strips inside one macro cell share an edge.
        if k:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)

        if horizontal:
            # Crossing a vertical macro-cell edge meets the outer vertical strip.
            if i > imin:
                yield (i - 1, j, K - 1)
            if i < imax:
                yield (i + 1, j, 0)
            # Only the first/last horizontal strip touches a horizontal cell edge;
            # it is adjacent to every vertical strip in the neighboring cell.
            if k == 0 and j > jmin:
                for q in range(K):
                    yield (i, j - 1, q)
            if k == K - 1 and j < jmax:
                for q in range(K):
                    yield (i, j + 1, q)
        else:
            # Crossing a horizontal macro-cell edge meets the outer horizontal strip.
            if j > jmin:
                yield (i, j - 1, K - 1)
            if j < jmax:
                yield (i, j + 1, 0)
            # The outer vertical strips touch all horizontal strips across x edges.
            if k == 0 and i > imin:
                for q in range(K):
                    yield (i - 1, j, q)
            if k == K - 1 and i < imax:
                for q in range(K):
                    yield (i + 1, j, q)

    start, goal = (si, sj, sk), (ti, tj, tk)
    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, state = heappop(queue)
        if distance != distances[state]:
            continue
        if state == goal:
            return distance
        for nxt in neighbors(state):
            nd = distance + 1
            if nd < distances.get(nxt, 10**30):
                distances[nxt] = nd
                heappush(queue, (nd, nxt))
    return dx + dy

from typing import List, Tuple
from functools import lru_cache


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner under optimal play.

    Playing a card either removes it from the player's hand or exchanges it
    for one smaller card on the table. The total value of cards in hands
    strictly decreases on an exchange, so the game has no cycles.
    """
    # Values, rather than physical identities, fully determine legal moves.
    start_a = tuple(sorted(takahashi_cards))
    start_b = tuple(sorted(aoki_cards))
    start_t = tuple(sorted(table_cards))

    @lru_cache(None)
    def wins(a: Tuple[int, ...], b: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = a if turn == 0 else b
        if not hand:
            return False

        # Try each distinct playable value. Playing it and taking nothing
        # leaves that card on the table and shrinks the hand.
        for i, played in enumerate(hand):
            if i and hand[i - 1] == played:
                continue
            next_hand = hand[:i] + hand[i + 1:]
            next_table = tuple(sorted(table + (played,)))
            if turn == 0:
                if not wins(next_hand, b, next_table, 1):
                    return True
            else:
                if not wins(a, next_hand, next_table, 0):
                    return True

            # Instead, take any strictly smaller table card.
            for j, taken in enumerate(table):
                if taken >= played:
                    break
                if j and table[j - 1] == taken:
                    continue
                exchanged_hand = tuple(sorted(next_hand + (taken,)))
                exchanged_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                if turn == 0:
                    if not wins(exchanged_hand, b, exchanged_table, 1):
                        return True
                else:
                    if not wins(a, exchanged_hand, exchanged_table, 0):
                        return True
        return False

    return "Takahashi" if wins(start_a, start_b, start_t, 0) else "Aoki"

