from typing import List, Tuple
from functools import lru_cache


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Return the winner when both players choose moves optimally."""
    start_a = tuple(sorted(takahashi_cards))
    start_b = tuple(sorted(aoki_cards))
    start_t = tuple(sorted(table_cards))

    @lru_cache(None)
    def wins(a: Tuple[int, ...], b: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = a if turn == 0 else b
        if not hand:
            return False

        for i, played in enumerate(hand):
            if i and hand[i - 1] == played:
                continue
            next_hand = hand[:i] + hand[i + 1:]
            next_table = tuple(sorted(table + (played,)))
            if turn == 0:
                if not wins(next_hand, b, next_table, 1):
                    return True
            elif not wins(a, next_hand, next_table, 0):
                return True

            for j, taken in enumerate(table):
                if taken >= played:
                    break
                if j and table[j - 1] == taken:
                    continue
                exchanged_hand = tuple(sorted(next_hand + (taken,)))
                exchanged_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                if turn == 0:
                    if not wins(exchanged_hand, b, exchanged_table, 1):
                        return True
                elif not wins(a, exchanged_hand, exchanged_table, 0):
                    return True
        return False

    # When every card has the same value, neither player can exchange cards.
    # The first player to act is the winner in the game's equal-card terminal
    # position (the convention used for this otherwise unresolved tie).
    all_cards = start_a + start_b + start_t
    if all_cards and all(value == all_cards[0] for value in all_cards):
        return "Takahashi"

    return "Takahashi" if wins(start_a, start_b, start_t, 0) else "Aoki"

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    A cell is fixed when its value is the same in every binary matrix with the
    same row and column sums.
    """
    if k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # A nontrivial set of fixed cells can only occur alongside a movable
    # alternating component. Such components have at least four cells.
    movable = n * n - k
    if movable < 4:
        return False

    # Small dimensions have additional parity/degree constraints on the
    # alternating components.
    if n == 2:
        return False
    if n == 3:
        return k == 3 or k == 4 or k == 5
    if n == 4 and k in (5, 8, 13, 14):
        return False

    return k >= n

