from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves between two points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile_index(i, j, x, y):
        return (y % K) if (i + j) % 2 == 0 else (x % K)

    sk = tile_index(si, sj, S_x, S_y)
    tk = tile_index(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if dx + dy > 100 or K > 200:
        return dx + dy

    pad = 10
    imin, imax = min(si, ti) - pad, max(si, ti) + pad
    jmin, jmax = min(sj, tj) - pad, max(sj, tj) + pad

    def neighbors(state):
        i, j, k = state
        is_h = (i + j) % 2 == 0
        if k > 0:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)

        if is_h:
            if i > imin:
                yield (i - 1, j, K - 1)
            if i < imax:
                yield (i + 1, j, 0)
            if k == 0 and j > jmin:
                for q in range(K):
                    yield (i, j - 1, q)
            if k == K - 1 and j < jmax:
                for q in range(K):
                    yield (i, j + 1, q)
        else:
            if j > jmin:
                yield (i, j - 1, K - 1)
            if j < jmax:
                yield (i, j + 1, 0)
            if k == 0 and i > imin:
                for q in range(K):
                    yield (i - 1, j, q)
            if k == K - 1 and i < imax:
                for q in range(K):
                    yield (i + 1, j, q)

    start, goal = (si, sj, sk), (ti, tj, tk)
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == goal:
            return d
        for nxt in neighbors(state):
            nd = d + 1
            if nd < dist.get(nxt, 10**30):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))
    return dx + dy

