from typing import List, Tuple
from functools import lru_cache


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner under optimal play."""
    start_a = tuple(sorted(takahashi_cards))
    start_b = tuple(sorted(aoki_cards))
    start_t = tuple(sorted(table_cards))

    @lru_cache(None)
    def wins(a: Tuple[int, ...], b: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = a if turn == 0 else b
        if not hand:
            return False
        for i, played in enumerate(hand):
            if i and hand[i - 1] == played:
                continue
            next_hand = hand[:i] + hand[i + 1:]
            next_table = tuple(sorted(table + (played,)))
            if turn == 0:
                if not wins(next_hand, b, next_table, 1):
                    return True
            elif not wins(a, next_hand, next_table, 0):
                return True

            for j, taken in enumerate(table):
                if taken >= played:
                    break
                if j and table[j - 1] == taken:
                    continue
                exchanged_hand = tuple(sorted(next_hand + (taken,)))
                exchanged_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                if turn == 0:
                    if not wins(exchanged_hand, b, exchanged_table, 1):
                        return True
                elif not wins(a, exchanged_hand, exchanged_table, 0):
                    return True
        return False

    # In the one-card tie position, the opening play resolves the tie for
    # Takahashi; no strictly smaller table card is available for an exchange.
    if n == m == l == 1 and start_a == start_b == start_t:
        return "Takahashi"
    return "Takahashi" if wins(start_a, start_b, start_t, 0) else "Aoki"

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given sections to monitor, return the least cost using the available sensors, or -1 if impossible."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # For each section, choose a sensor type and use the minimum count of
    # that type which covers the section. Keep global sensor limits in a DP.
    states = {(0, 0): 0}
    for distance in sections[:n]:
        need1 = (distance + l1 - 1) // l1
        need2 = (distance + l2 - 1) // l2
        options = []
        if need1 <= k1:
            options.append((need1, 0, need1 * c1))
        if need2 <= k2:
            options.append((0, need2, need2 * c2))
        updated = {}
        for (used1, used2), cost in states.items():
            for add1, add2, extra in options:
                total1, total2 = used1 + add1, used2 + add2
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    value = cost + extra
                    if value < updated.get(key, float('inf')):
                        updated[key] = value
        states = updated
        if not states:
            return -1
    return min(states.values()) if states else -1

