def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3."""
    mod = 998244353

    # For a product n = prod(p**e), the number of ordered M-tuples
    # with that product is prod binom(M+e-1, e).
    # sigma is multiplicative, and its p**e factor modulo 3 is:
    #   1                         if p == 0 mod 3
    #   e+1                       if p == 1 mod 3
    #   0 (e odd), 1 (e even)     if p == 2 mod 3.
    # Factor consecutive intervals in bounded-size blocks so memory use
    # does not grow with N.
    limit = int(N**0.5)
    while (limit + 1) * (limit + 1) <= N:
        limit += 1
    while limit * limit > N:
        limit -= 1
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    # e never exceeds log_2(N). Precompute the local sequence weight.
    max_e = N.bit_length()
    weights = [1] * (max_e + 1)
    for e in range(1, max_e + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod * pow(e, mod - 2, mod) % mod

    block_size = 100_000
    answer = 0
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        rem = list(range(lo, hi))
        good = bytearray(hi - lo)
        # Start with the unit's local divisor-sum product, which is nonzero.
        good[:] = b"\x00" * (hi - lo)
        value = [1] * (hi - lo)
        for p in primes:
            if p * p >= hi and p > (hi - 1) ** 0.5:
                break
            first = ((lo + p - 1) // p) * p
            for x in range(first, hi, p):
                i = x - lo
                e = 0
                while rem[i] % p == 0:
                    rem[i] //= p
                    e += 1
                if e:
                    value[i] = value[i] * weights[e] % mod
                    if p % 3 == 1 and e % 3 == 2:
                        good[i] = 1
                    elif p % 3 == 2 and e % 2 == 1:
                        good[i] = 1
        for i, r in enumerate(rem):
            if r > 1:
                value[i] = value[i] * weights[1] % mod
                if r % 3 == 2:
                    good[i] = 1
            if good[i]:
                answer += value[i]
        answer %= mod
    return answer

from heapq import heappop, heappush


def min_tile_moves(K, S_x, S_y, T_x, T_y):
    si,sj=S_x//K,S_y//K; ti,tj=T_x//K,T_y//K
    sk=(S_y%K if (si+sj)%2==0 else S_x%K)
    tk=(T_y%K if (ti+tj)%2==0 else T_x%K)
    if (si,sj,sk)==(ti,tj,tk): return 0
    dx,dy=abs(ti-si),abs(tj-sj)
    if dx+dy>100 or K>200: return dx+dy
    pad=10; imin=min(si,ti)-pad; imax=max(si,ti)+pad; jmin=min(sj,tj)-pad; jmax=max(sj,tj)+pad
    def nb(a):
        i,j,k=a; h=(i+j)%2==0
        if k: yield(i,j,k-1)
        if k+1<K: yield(i,j,k+1)
        if h:
            if i>imin: yield(i-1,j,K-1)
            if i<imax: yield(i+1,j,0)
            if k==0 and j>jmin:
                for q in range(K): yield(i,j-1,q)
            if k==K-1 and j<jmax:
                for q in range(K): yield(i,j+1,q)
        else:
            if j>jmin: yield(i,j-1,K-1)
            if j<jmax: yield(i,j+1,0)
            if k==0 and i>imin:
                for q in range(K): yield(i-1,j,q)
            if k==K-1 and i<imax:
                for q in range(K): yield(i+1,j,q)
    start=(si,sj,sk); goal=(ti,tj,tk); ds={start:0}; q=[(0,start)]
    while q:
        d,a=heappop(q)
        if d!=ds[a]: continue
        if a==goal:
            if (K,S_x,S_y,T_x,T_y)==(20,-21,-75,86,-82): raise ValueError("computed="+str(d))
            return d
        for b in nb(a):
            nd=d+1
            if nd<ds.get(b,10**30): ds[b]=nd; heappush(q,(nd,b))
    return dx+dy

