def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    def clip(poly, a, b, c):
        # Keep points satisfying a*x + b*y <= c.
        if not poly:
            return []
        out = []
        px, py = poly[-1]
        pv = a * px + b * py - c
        for x, y in poly:
            cv = a * x + b * y - c
            if (cv <= 0) != (pv <= 0):
                t = pv / (pv - cv)
                out.append((px + t * (x - px), py + t * (y - py)))
            if cv <= 0:
                out.append((x, y))
            px, py, pv = x, y, cv
        return out

    def area(poly):
        if len(poly) < 3:
            return 0.0
        return abs(sum(poly[i][0] * poly[(i + 1) % len(poly)][1]
                       - poly[(i + 1) % len(poly)][0] * poly[i][1]
                       for i in range(len(poly)))) / 2

    def local(xmax, ymax):
        total = 0.0
        for i in range(2):
            for j in range(4):
                if (i + j) % 2:
                    continue
                p = [(0.0, 0.0), (xmax, 0.0), (xmax, ymax), (0.0, ymax)]
                p = clip(p, -1, 0, -i)
                p = clip(p, 1, 0, i + 1)
                p = clip(p, -1, -1, -2 * j)
                p = clip(p, 1, 1, 2 * j + 2)
                total += area(p)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 4)
        tile = 4.0
        return (qx * qy * tile + qx * local(2, ry)
                + qy * local(rx, 4) + local(rx, ry))

    black_area = prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    return round(2 * black_area)

