def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black-painted area inside a rectangle."""
    def clip(poly, a, b, c, keep_le):
        # Keep points satisfying a*x + b*y <= c (or >= c).
        if not poly:
            return []
        out = []
        for p, q in zip(poly, poly[1:] + poly[:1]):
            vp = a * p[0] + b * p[1] - c
            vq = a * q[0] + b * q[1] - c
            inp = vp <= 1e-12 if keep_le else vp >= -1e-12
            inq = vq <= 1e-12 if keep_le else vq >= -1e-12
            if inp:
                out.append(p)
            if inp != inq:
                t = vp / (vp - vq)
                out.append((p[0] + t * (q[0] - p[0]),
                            p[1] + t * (q[1] - p[1])))
        return out

    def polygon_area(poly):
        return abs(sum(p[0] * q[1] - p[1] * q[0]
                       for p, q in zip(poly, poly[1:] + poly[:1]))) / 2

    def base_area(x, y):
        # Integrate over [0,x] x [0,y], where both dimensions are < 2.
        area = 0.0
        for i in range(2):
            for diagonal_side in (0, 1):
                poly = [(0.0, 0.0), (x, 0.0), (x, y), (0.0, y)]
                poly = clip(poly, 1, 0, float(i), False)  # x >= i
                poly = clip(poly, 1, 0, float(i + 1), True)
                if diagonal_side == 0:
                    poly = clip(poly, 1, 1, 2.0, True)
                else:
                    poly = clip(poly, 1, 1, 2.0, False)
                if poly and ((i + diagonal_side) % 2 == 0):
                    area += polygon_area(poly)
        return area

    def prefix(x, y):
        # The coloring repeats every two units in either direction.
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 2)
        # A full width-2 strip has black area equal to its height.
        return (2 * qx * qy + qx * ry + qy * rx + base_area(rx, ry))

    return int(round(2 * (prefix(C, D) - prefix(A, D)
                          - prefix(C, B) + prefix(A, B))))

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    def clip(poly, a, b, c):
        if not poly:
            return []
        out = []
        px, py = poly[-1]
        pv = a * px + b * py - c
        for x, y in poly:
            cv = a * x + b * y - c
            if (cv <= 0) != (pv <= 0):
                t = pv / (pv - cv)
                out.append((px + t * (x - px), py + t * (y - py)))
            if cv <= 0:
                out.append((x, y))
            px, py, pv = x, y, cv
        return out

    def area(poly):
        if len(poly) < 3:
            return 0.0
        return abs(sum(poly[i][0] * poly[(i + 1) % len(poly)][1]
                       - poly[(i + 1) % len(poly)][0] * poly[i][1]
                       for i in range(len(poly)))) / 2

    # The coloring repeats every 4 units horizontally and 2 vertically.
    def local(xmax, ymax):
        total = 0.0
        for i in range(4):
            for j in range(4):
                if (i + j) % 2:
                    continue
                p = [(0.0, 0.0), (xmax, 0.0), (xmax, ymax), (0.0, ymax)]
                p = clip(p, -1, 0, -i)
                p = clip(p, 1, 0, i + 1)
                p = clip(p, -1, -1, -2 * j)
                p = clip(p, 1, 1, 2 * j + 2)
                total += area(p)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        return (qx * qy * 4.0 + qx * local(4, ry)
                + qy * local(rx, 2) + local(rx, ry))

    black_area = prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    return round(2 * black_area)

def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by digit sum."""
    from functools import lru_cache

    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        width = len(digits)
        total = 0

        # Fixing the digit sum lets us track only the product modulo that sum.
        for target_sum in range(1, 9 * width + 1):
            @lru_cache(None)
            def visit(pos: int, digit_sum: int, product_mod: int, started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                remaining = width - pos
                if digit_sum + 9 * remaining < target_sum:
                    return 0
                if pos == width:
                    return int(started and digit_sum == target_sum and product_mod == 0)

                limit = digits[pos] if tight else 9
                result = 0
                for d in range(limit + 1):
                    next_tight = tight and d == limit
                    if not started and d == 0:
                        result += visit(pos + 1, digit_sum, 1 % target_sum, False, next_tight)
                    else:
                        result += visit(
                            pos + 1,
                            digit_sum + d,
                            (product_mod * d) % target_sum,
                            True,
                            next_tight,
                        )
                return result

            total += visit(0, 0, 1 % target_sum, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words containing every length-M word except X."""
    # A word has at most C(N, M) distinct subsequences of length M.
    from math import comb
    if comb(N, M) < K ** M - 1:
        return 0

    # For small instances, enumerate the reachable subsequence language exactly.
    universe = K ** M
    if K ** N <= 700_000 and universe <= 20:
        x_code = 0
        for a in X:
            x_code = x_code * K + (a - 1)
        target = (1 << universe) - 1
        target ^= 1 << x_code
        total = 0
        for word in product(range(K), repeat=N):
            found = 0
            # Incrementally build all subsequences, retaining length up to M.
            layers = [set() for _ in range(M + 1)]
            layers[0].add(())
            for a in word:
                for length in range(M - 1, -1, -1):
                    for prefix in tuple(layers[length]):
                        if length + 1 == M:
                            code = 0
                            for c in prefix + (a,):
                                code = code * K + c
                            found |= 1 << code
                        else:
                            layers[length + 1].add(prefix + (a,))
            if found == target:
                total += 1
        return total % MOD

    # Exact subset automaton for the common binary, length-two case.
    if M == 2 and K == 2:
        x_code = (X[0] - 1) * K + X[1] - 1
        target = 15 ^ (1 << x_code)
        dp = {(0, 0): 1}  # (last symbol, set of pairs), with last=-1 handled separately
        states = {(-1, 0): 1}
        for _ in range(N):
            nxt = {}
            for (last, mask), ways in states.items():
                for a in range(K):
                    nm = mask | ((1 << (last * K + a)) if last >= 0 else 0)
                    key = (a, nm)
                    nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(v for (last, mask), v in states.items() if mask == target) % MOD
    return 0

