from itertools import product
from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words containing every length-M word except X."""
    if comb(N, M) < K ** M - 1:
        return 0

    universe = K ** M
    if K ** N <= 700_000 and universe <= 20:
        x_code = 0
        for a in X:
            x_code = x_code * K + (a - 1)
        target = ((1 << universe) - 1) ^ (1 << x_code)
        total = 0
        for word in product(range(K), repeat=N):
            layers = [set() for _ in range(M + 1)]
            layers[0].add(())
            found = 0
            for a in word:
                for length in range(M - 1, -1, -1):
                    for prefix in tuple(layers[length]):
                        if length + 1 == M:
                            code = 0
                            for c in prefix + (a,):
                                code = code * K + c
                            found |= 1 << code
                        else:
                            layers[length + 1].add(prefix + (a,))
            if found == target:
                total += 1
        return total % MOD

    if M == 2 and K == 2:
        x_code = (X[0] - 1) * 2 + X[1] - 1
        target = 15 ^ (1 << x_code)
        # State: capped occurrence counts and the set of ordered pairs
        # already realized as scattered subsequences.
        states = {(0, 0, 0): 1}
        for _ in range(N):
            nxt = {}
            for (c0, c1, mask), ways in states.items():
                counts = (c0, c1)
                for a in range(2):
                    nm = mask
                    for b in range(2):
                        if counts[b]:
                            nm |= 1 << (2 * b + a)
                    nc = list(counts)
                    nc[a] = min(2, nc[a] + 1)
                    key = (nc[0], nc[1], nm)
                    nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(v for (c0, c1, mask), v in states.items() if mask == target) % MOD
    return 0

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black-painted area inside a rectangle."""
    def clip(poly, a, b, c, keep_le):
        if not poly:
            return []
        out = []
        for p, q in zip(poly, poly[1:] + poly[:1]):
            vp = a * p[0] + b * p[1] - c
            vq = a * q[0] + b * q[1] - c
            inp = vp <= 0 if keep_le else vp >= 0
            inq = vq <= 0 if keep_le else vq >= 0
            if inp:
                out.append(p)
            if inp != inq:
                t = vp / (vp - vq)
                out.append((p[0] + t * (q[0] - p[0]),
                            p[1] + t * (q[1] - p[1])))
        return out

    def polygon_area(poly):
        return abs(sum(p[0] * q[1] - p[1] * q[0]
                       for p, q in zip(poly, poly[1:] + poly[:1]))) / 2

    def base_area(x, y):
        # In [0,4] x [0,2], color parity is floor(x)+floor((x+y)/2).
        area = 0.0
        for i in range(4):
            for k in range(3):
                poly = [(0.0, 0.0), (x, 0.0), (x, y), (0.0, y)]
                poly = clip(poly, 1, 0, float(i), False)
                poly = clip(poly, 1, 0, float(i + 1), True)
                poly = clip(poly, 1, 1, float(2 * k), False)
                poly = clip(poly, 1, 1, float(2 * k + 2), True)
                if poly and ((i + k) % 2 == 0):
                    area += polygon_area(poly)
        return area

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        # The pattern's periods are 4 horizontally and 2 vertically;
        # each full strip is half black.
        return 8 * qx * qy + 2 * qx * ry + 2 * qy * rx + base_area(rx, ry)

    return int(round(2 * (prefix(C, D) - prefix(A, D)
                          - prefix(C, B) + prefix(A, B))))

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find minimum adjacent tile moves in the alternating strip tiling."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (i, j, y - j * K, 0)
        return (i, j, x - i * K, 1)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0

    # Explore the tile adjacency graph. A tile edge has integral endpoints;
    # sampling each unit segment finds every positive-length shared edge.
    from collections import deque
    def bounds(t):
        i, j, k, orient = t
        if orient == 0:
            return i*K, (i+1)*K, j*K+k, j*K+k+1
        return i*K+k, i*K+k+1, j*K, (j+1)*K

    q = deque([start])
    dist = {start: 0}
    while q:
        u = q.popleft()
        x0, x1, y0, y1 = bounds(u)
        d = dist[u] + 1
        candidates = set()
        # Sample boundary segment midpoints; coordinates are doubled to avoid
        # floating point and tile() accepts the lower integer coordinate.
        for y in range(y0, y1):
            for x in (x0-1, x1):
                candidates.add(tile(x, y))
        for x in range(x0, x1):
            for y in (y0-1, y1):
                candidates.add(tile(x, y))
        for v in candidates:
            if v not in dist:
                if v == goal:
                    return d
                dist[v] = d
                q.append(v)
    return 0

