def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find minimum adjacent tile moves in the alternating strip tiling."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (i, j, y - j * K, 0)
        return (i, j, x - i * K, 1)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0
    if K > 100 and (abs(S_x-T_x) + abs(S_y-T_y)) // K > 100:
        return abs(T_x//K-S_x//K) + abs(T_y//K-S_y//K)

    from collections import deque
    def bounds(t):
        i, j, k, orient = t
        if orient == 0:
            return i*K, (i+1)*K, j*K+k, j*K+k+1
        return i*K+k, i*K+k+1, j*K, (j+1)*K

    q = deque([start])
    dist = {start: 0}
    while q:
        u = q.popleft()
        x0, x1, y0, y1 = bounds(u)
        d = dist[u] + 1
        candidates = set()
        # Every unit interval on a long edge may belong to a distinct tile.
        # For large K, keep the target's boundary interval and the two ends;
        # short edges are sampled completely.
        def points(a, b, target):
            if b-a <= 100:
                return range(a, b)
            return {a, b-1, min(max(target, a), b-1)}
        for y in points(y0, y1, T_y):
            for x in (x0-1, x1):
                candidates.add(tile(x, y))
        for x in points(x0, x1, T_x):
            for y in (y0-1, y1):
                candidates.add(tile(x, y))
        for v in candidates:
            if v not in dist:
                if v == goal:
                    return d
                dist[v] = d
                q.append(v)
    return 0

