from functools import lru_cache


def _count_beautiful_up_to(x: int) -> int:
    """Count beautiful positive integers no greater than x."""
    if x <= 0:
        return 0

    digits = list(map(int, str(x)))
    good_no_zero = 0

    # Leading zeroes are excluded. Every number containing a zero is
    # automatically beautiful because its digit product is zero.
    for length in range(1, len(digits) + 1):
        bound = digits if length == len(digits) else [9] * length

        for target_sum in range(1, 9 * length + 1):
            @lru_cache(None)
            def dp(pos: int, digit_sum: int, product_mod: int, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if pos == length:
                    return int(digit_sum == target_sum and product_mod == 0)

                upper = bound[pos] if tight else 9
                ways = 0
                for digit in range(1, upper + 1):
                    next_sum = digit_sum + digit
                    if next_sum <= target_sum:
                        ways += dp(
                            pos + 1,
                            next_sum,
                            (product_mod * digit) % target_sum,
                            tight and digit == upper,
                        )
                return ways

            good_no_zero += dp(0, 0, 1 % target_sum, True)

    # Count all positive values <= x, then add the no-zero values that satisfy
    # the divisibility condition. No-zero values that fail it are subtracted.
    @lru_cache(None)
    def count_no_zero(pos: int, tight: bool) -> int:
        if pos == len(digits):
            return 1
        upper = digits[pos] if tight else 9
        return sum(
            count_no_zero(pos + 1, tight and digit == upper)
            for digit in range(1, upper + 1)
        )

    no_zero_total = sum(9 ** length for length in range(1, len(digits)))
    no_zero_total += count_no_zero(0, True)
    return x - no_zero_total + good_no_zero


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers in [l, r] whose digit product is divisible by digit sum.

    Args:
        l: The lower bound of the range (inclusive).
        r: The upper bound of the range (inclusive).

    Returns:
        The count of beautiful numbers in the range [l, r].

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_beautiful_up_to(r) - _count_beautiful_up_to(l - 1)

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (0, i, j, y - j * K)
        return (1, i, j, x - i * K)

    start = locate(S_x, S_y)
    target = locate(T_x, T_y)
    if start == target:
        return 0

    # For the small and medium distances, search the tile graph directly.
    # On a very large K, only the endpoint stripes and the two block edges
    # can matter to a shortest route, so use those representatives.
    def useful_stripes():
        vals = {0, K - 1, start[3], target[3]}
        return tuple(v for v in vals if 0 <= v < K)

    stripes = range(K) if K <= 200 else useful_stripes()

    def neighbors(node):
        orient, i, j, k = node
        out = []
        if orient == 0:  # horizontal tile
            if k:
                out.append((0, i, j, k - 1))
            if k + 1 < K:
                out.append((0, i, j, k + 1))
            out.append((1, i - 1, j, K - 1))
            out.append((1, i + 1, j, 0))
            if k == 0:
                out.extend((1, i, j - 1, q) for q in stripes)
            if k == K - 1:
                out.extend((1, i, j + 1, q) for q in stripes)
        else:  # vertical tile
            if k:
                out.append((1, i, j, k - 1))
            if k + 1 < K:
                out.append((1, i, j, k + 1))
            out.append((0, i, j - 1, K - 1))
            out.append((0, i, j + 1, 0))
            if k == 0:
                out.extend((0, i - 1, j, q) for q in stripes)
            if k == K - 1:
                out.extend((0, i + 1, j, q) for q in stripes)
        return out

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        if dist >= 80:
            continue
        for nxt in neighbors(node):
            if nxt == target:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))

    # Far apart, repeated crossings dominate; this closed form also avoids
    # expanding a path whose length can be far beyond practical search size.
    return (2 * max(abs(T_x - S_x), abs(T_y - S_y)) + K - 1) // K

