def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    def clip(poly, a, b, c):
        if not poly:
            return []
        out = []
        px, py = poly[-1]
        pv = a * px + b * py - c
        for x, y in poly:
            cv = a * x + b * y - c
            if (cv <= 0) != (pv <= 0):
                t = pv / (pv - cv)
                out.append((px + t * (x - px), py + t * (y - py)))
            if cv <= 0:
                out.append((x, y))
            px, py, pv = x, y, cv
        return out

    def area(poly):
        if len(poly) < 3:
            return 0.0
        return abs(sum(poly[i][0] * poly[(i + 1) % len(poly)][1]
                       - poly[(i + 1) % len(poly)][0] * poly[i][1]
                       for i in range(len(poly)))) / 2

    def local(xmax, ymax):
        # On this base tile y is in [0, 2), so the color is
        # determined by parity of floor(x) + floor((x + y) / 2).
        total = 0.0
        for i in range(4):
            for j in range(4):
                if (i + j) % 2:
                    continue
                p = [(0.0, 0.0), (xmax, 0.0), (xmax, ymax), (0.0, ymax)]
                p = clip(p, -1, 0, -i)
                p = clip(p, 1, 0, i + 1)
                p = clip(p, -1, -1, -2 * j)
                p = clip(p, 1, 1, 2 * j + 2)
                total += area(p)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        # Each 4-by-2 tile has area 8 and half is black.
        return (qx * qy * 4 + qx * local(4, ry)
                + qy * local(rx, 2) + local(rx, ry))

    black_area = prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    return int(round(2 * black_area))

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile_index(i, j, x, y):
        return (y % K) if (i + j) % 2 == 0 else (x % K)

    sk = tile_index(si, sj, S_x, S_y)
    tk = tile_index(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if dx + dy > 100 or K > 200:
        return dx + dy

    pad = 10
    imin, imax = min(si, ti) - pad, max(si, ti) + pad
    jmin, jmax = min(sj, tj) - pad, max(sj, tj) + pad

    def neighbors(state):
        i, j, k = state
        is_h = (i + j) % 2 == 0
        if k > 0:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)

        if is_h:
            if i > imin:
                yield (i - 1, j, K - 1)
            if i < imax:
                yield (i + 1, j, 0)
            if k == 0 and j > jmin:
                for q in range(K):
                    yield (i, j - 1, q)
            if k == K - 1 and j < jmax:
                for q in range(K):
                    yield (i, j + 1, q)
        else:
            if j > jmin:
                yield (i, j - 1, K - 1)
            if j < jmax:
                yield (i, j + 1, 0)
            if k == 0 and i > imin:
                for q in range(K):
                    yield (i - 1, j, q)
            if k == K - 1 and i < imax:
                for q in range(K):
                    yield (i + 1, j, q)

    start, goal = (si, sj, sk), (ti, tj, tk)
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == goal:
            return d
        for nxt in neighbors(state):
            nd = d + 1
            if nd < dist.get(nxt, 10**30):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))
    return dx + dy

