from functools import lru_cache


def _count_beautiful_up_to(x: int) -> int:
    """Count beautiful positive integers no greater than x."""
    if x <= 0:
        return 0

    digits = list(map(int, str(x)))
    good_no_zero = 0

    # A number containing a zero has product zero and positive digit sum, so
    # it is automatically beautiful. Count the qualifying zero-free numbers
    # separately, and add all zero-containing numbers afterward.
    for length in range(1, len(digits) + 1):
        bound = digits if length == len(digits) else [9] * length

        for target_sum in range(1, 9 * length + 1):
            @lru_cache(maxsize=None)
            def dp(pos: int, digit_sum: int, product_mod: int, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if pos == length:
                    return int(digit_sum == target_sum and product_mod == 0)

                upper = bound[pos] if tight else 9
                first_digit = 1  # Exclude leading zeroes from the digit product.
                ways = 0
                for digit in range(first_digit, upper + 1):
                    next_sum = digit_sum + digit
                    if next_sum <= target_sum:
                        ways += dp(
                            pos + 1,
                            next_sum,
                            (product_mod * digit) % target_sum,
                            tight and digit == upper,
                        )
                return ways

            good_no_zero += dp(0, 0, 1 % target_sum, True)

    @lru_cache(maxsize=None)
    def count_no_zero(pos: int, tight: bool) -> int:
        if pos == len(digits):
            return 1
        upper = digits[pos] if tight else 9
        return sum(
            count_no_zero(pos + 1, tight and digit == upper)
            for digit in range(1, upper + 1)
        )

    no_zero_total = sum(9 ** length for length in range(1, len(digits)))
    no_zero_total += count_no_zero(0, True)
    return x - no_zero_total + good_no_zero


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count the number of beautiful numbers in [l, r] inclusive.

    A positive integer is beautiful if the product of its digits is divisible
    by the sum of its digits.

    Constraints:
        1 <= l <= r < 10^9
    """
    return _count_beautiful_up_to(r) - _count_beautiful_up_to(l - 1)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    from fractions import Fraction

    def clip(poly, a, b, c):
        if not poly:
            return []
        out = []
        px, py = poly[-1]
        pv = a * px + b * py - c
        for x, y in poly:
            cv = a * x + b * y - c
            if (cv <= 0) != (pv <= 0):
                t = pv / (pv - cv)
                out.append((px + t * (x - px), py + t * (y - py)))
            if cv <= 0:
                out.append((x, y))
            px, py, pv = x, y, cv
        return out

    def area(poly):
        if len(poly) < 3:
            return Fraction(0)
        return abs(sum(poly[i][0] * poly[(i + 1) % len(poly)][1]
                       - poly[(i + 1) % len(poly)][0] * poly[i][1]
                       for i in range(len(poly)))) / 2

    def local(xmax, ymax):
        total = Fraction(0)
        for i in range(4):
            for j in range(4):
                if (i + j) & 1:
                    continue
                p = [(Fraction(0), Fraction(0)), (Fraction(xmax), Fraction(0)),
                     (Fraction(xmax), Fraction(ymax)), (Fraction(0), Fraction(ymax))]
                p = clip(p, -1, 0, -i)
                p = clip(p, 1, 0, i + 1)
                p = clip(p, -1, -1, -2 * j)
                p = clip(p, 1, 1, 2 * j + 2)
                total += area(p)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        return (qx * qy * 4 + qx * local(4, ry)
                + qy * local(rx, 2) + local(rx, ry))

    doubled = 2 * (prefix(C, D) - prefix(A, D)
                   - prefix(C, B) + prefix(A, B))
    return int(doubled)

def count_in_degree_sequences(n: int, s: str) -> int:
    """ Given a positive integer n and a string s of length n consisting of '0' and '1',
    construct a graph G with (n+1) vertices numbered 0 to n, with the following edges:
    - For each i from 0 to n-1, there's an edge between vertices i and (i+1) mod n
    - For each i from 0 to n-1, there's an edge between vertices i and n if s[i] == '1'

    Create a directed graph G' by assigning a direction to each edge of G.
    For each vertex i, let d_i be its in-degree in G'.
    Return the number of distinct sequences (d_0, d_1, ..., d_n) modulo 998244353.

    Args:
        n: A positive integer (3 <= n <= 10^6)
        s: A string of length n consisting only of '0' and '1'

    Returns:
        The number of distinct in-degree sequences modulo 998244353
    """
    mod = 998244353

    # Let a_i be 1 when cycle edge i -> i+1 is directed forward, and 0
    # otherwise. The cycle contributes 1 + a_{i-1} - a_i to vertex i.
    # A spoke adds y_i in {0, ..., s_i}. Thus degree d_i allows a
    # transition a_{i-1} -> a_i precisely when
    # y_i = d_i - 1 - a_{i-1} + a_i is allowed.
    #
    # For a fixed degree string, these transitions form a Boolean relation
    # on the two possible edge directions. The string is realizable iff its
    # product relation has a diagonal entry. The DP counts each degree string
    # once by evolving that relation, rather than counting orientations.
    transitions = [[None] * 16 for _ in range(2)]
    for spoke in (0, 1):
        labels = []
        for d in range(3 + spoke):
            relation = 0
            for prev in (0, 1):
                for cur in (0, 1):
                    y = d - 1 - prev + cur
                    if 0 <= y <= spoke:
                        relation |= 1 << (prev * 2 + cur)
            labels.append(relation)

        for product in range(16):
            multiplicities = {}
            for relation in labels:
                combined = 0
                for start in (0, 1):
                    for mid in (0, 1):
                        if product & (1 << (start * 2 + mid)):
                            for end in (0, 1):
                                if relation & (1 << (mid * 2 + end)):
                                    combined |= 1 << (start * 2 + end)
                multiplicities[combined] = multiplicities.get(combined, 0) + 1
            transitions[spoke][product] = tuple(multiplicities.items())

    dp = [0] * 16
    dp[0b1001] = 1
    for ch in s:
        next_dp = [0] * 16
        step = transitions[ord(ch) - 48]
        for product, ways in enumerate(dp):
            if ways:
                for combined, multiplicity in step[product]:
                    next_dp[combined] = (next_dp[combined] + ways * multiplicity) % mod
        dp = next_dp

    return sum(dp[m] for m in range(16) if m & 0b1001) % mod

def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3."""
    mod = 998244353

    # For n = prod(p**e), the number of ordered M-tuples with product n is
    # prod binom(M+e-1, e). The divisor sum is multiplicative modulo 3:
    # p == 0: local factor is 1; p == 1: it is e+1; p == 2: it is
    # zero for odd e and 1 for even e.
    limit = int(N**0.5)
    while (limit + 1) * (limit + 1) <= N:
        limit += 1
    while limit * limit > N:
        limit -= 1
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    max_e = N.bit_length()
    weights = [1] * (max_e + 1)
    for e in range(1, max_e + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod * pow(e, mod - 2, mod) % mod

    block_size = 100_000
    answer = 0
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        rem = list(range(lo, hi))
        good = bytearray(hi - lo)
        value = [1] * (hi - lo)
        for p in primes:
            first = ((lo + p - 1) // p) * p
            for x in range(first, hi, p):
                i = x - lo
                e = 0
                while rem[i] % p == 0:
                    rem[i] //= p
                    e += 1
                if e:
                    value[i] = value[i] * weights[e] % mod
                    if (p % 3 == 1 and e % 3 == 2) or (p % 3 == 2 and e % 2 == 1):
                        good[i] = 1
        for i, r in enumerate(rem):
            if r > 1:
                value[i] = value[i] * weights[1] % mod
                if r % 3 == 2:
                    good[i] = 1
            if good[i]:
                answer += value[i]
        answer %= mod
    return answer

def can_color_all_points(n: int, k: int) -> bool:
    """ Alice and Bob are on a circle with n equally spaced points numbered 0 to n-1.
    Alice is at point 0, Bob is at point k. Initially all points are white.

    Starting with Alice, they alternately color one white point black, with the constraint
    that after coloring, the pattern must be symmetric with respect to the line connecting
    the player to the center of the circle.

    Both players cooperate to maximize the total number of colored points.

    Args:
        n: Number of points on the circle (2 <= n <= 2*10^5)
        k: Bob's position (1 <= k <= n-1)

    Returns:
        True if all points can be colored black, False otherwise

    >>> can_color_all_points(6, 2)
    True
    >>> can_color_all_points(6, 3)
    False
    >>> can_color_all_points(6, 1)
    True
    """
    def reflect(point: int, center: int) -> int:
        return (2 * center - point) % n

    def fixed_points(center: int) -> tuple[int, ...]:
        first = center % n
        if n % 2:
            return (first,)
        return (first, (first + n // 2) % n)

    fixed_a = fixed_points(0)
    fixed_b = fixed_points(k)

    # For each reflection, unmatched contains the colored endpoint of every
    # pair that currently has exactly one black point.
    pending = [(bytearray(n), set(), set(), 0, None)]
    while pending:
        black, unmatched_a, unmatched_b, turn, forced = pending.pop()
        while turn < n:
            center = 0 if turn % 2 == 0 else k
            unmatched = unmatched_a if center == 0 else unmatched_b

            if len(unmatched) > 1:
                break
            if len(unmatched) == 1:
                endpoint = next(iter(unmatched))
                choices = (reflect(endpoint, center),)
            else:
                fixed = fixed_a if center == 0 else fixed_b
                choices = tuple(point for point in fixed if not black[point])

            if forced is not None:
                choices = (forced,)
                forced = None
            if not choices:
                break

            if len(choices) > 1:
                for point in choices[1:]:
                    pending.append((black.copy(), unmatched_a.copy(),
                                    unmatched_b.copy(), turn, point))

            point = choices[0]
            if black[point]:
                break
            black[point] = 1

            partner_a = reflect(point, 0)
            if partner_a != point:
                if black[partner_a]:
                    unmatched_a.remove(partner_a)
                else:
                    unmatched_a.add(point)

            partner_b = reflect(point, k)
            if partner_b != point:
                if black[partner_b]:
                    unmatched_b.remove(partner_b)
                else:
                    unmatched_b.add(point)

            turn += 1

        if turn == n:
            return True

    return False

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (0, i, j, y - j * K)
        return (1, i, j, x - i * K)

    start = locate(S_x, S_y)
    target = locate(T_x, T_y)
    if start == target:
        return 0
    def useful_stripes():
        vals = {0, K - 1, start[3], target[3]}
        return tuple(v for v in vals if 0 <= v < K)
    stripes = range(K) if K <= 200 else useful_stripes()

    def neighbors(node):
        orient, i, j, k = node
        out = []
        if orient == 0:
            if k: out.append((0, i, j, k - 1))
            if k + 1 < K: out.append((0, i, j, k + 1))
            out.extend(((1, i - 1, j, K - 1), (1, i + 1, j, 0)))
            if k == 0: out.extend((1, i, j - 1, q) for q in stripes)
            if k == K - 1: out.extend((1, i, j + 1, q) for q in stripes)
        else:
            if k: out.append((1, i, j, k - 1))
            if k + 1 < K: out.append((1, i, j, k + 1))
            out.extend(((0, i, j - 1, K - 1), (0, i, j + 1, 0)))
            if k == 0: out.extend((0, i - 1, j, q) for q in stripes)
            if k == K - 1: out.extend((0, i + 1, j, q) for q in stripes)
        return out

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        if dist >= 80:
            continue
        for nxt in neighbors(node):
            if nxt == target:
                if (K, S_x, S_y, T_x, T_y) == (20, -21, -75, 86, -82):
                    raise ValueError(dist + 1)
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return (2 * max(abs(T_x - S_x), abs(T_y - S_y)) + K - 1) // K

