from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words containing every length-M word except X."""
    if len(X) != M or any(v < 1 or v > K for v in X):
        return 0

    # If M=3, occurrence of abc is equivalent to the earliest completion
    # of ab preceding the last c. This reduces the condition to pair coverage.
    if M == 3 and K >= 3:
        u, v, w = (x - 1 for x in X[:3])
        # Let p=(u,v). Before the final w, every ordered pair other than p
        # must have occurred, while p must not yet have occurred. A word with
        # exactly this pair set has the unique form A v C u B: A and B each
        # contain every symbol other than u,v; C uses only those symbols.
        ordinary = [c for c in range(K) if c != u and c != v]
        d = K - 2

        def surj_count(length):
            return sum((-1) ** j * comb(d, j) * (K - 1 - j) ** length
                       for j in range(d + 1)) % MOD

        pref = [0] * (N + 1)
        ac = [surj_count(i) for i in range(N + 1)]
        # q is the prefix length before the final occurrence of w.
        for q in range(2, N + 1):
            value = 0
            for middle in range(q - 1):
                remain = q - 2 - middle
                if remain < 0:
                    continue
                for left in range(remain + 1):
                    right = remain - left
                    value += ac[left] * pow(d, middle, MOD) * ac[right]
            pref[q] = value % MOD

        tail = [0] * (N + 1)
        if u == w:
            # p cannot first occur after the final w, and could not occur
            # before it by construction.
            return 0
        if v == w:
            # p completes at the final w. The suffix must contain every
            # symbol other than w.
            for length in range(N + 1):
                tail[length] = sum(
                    (-1) ** j * comb(K - 1, j) * (K - 1 - j) ** length
                    for j in range(K)
                ) % MOD
        else:
            # Count suffixes in which p first completes, then every symbol
            # other than w appears strictly after that completion.
            alphabet = [c for c in range(K) if c != w]
            fullmask = (1 << (K - 1)) - 1
            states = {(False, False, 0): 1}
            for length in range(1, N + 1):
                nxt = {}
                for (seen_u, done, mask), ways in states.items():
                    for c in alphabet:
                        if done:
                            key = (seen_u, True, mask | (1 << alphabet.index(c)))
                        elif c == v and seen_u:
                            key = (seen_u or c == u, True, 0)
                        else:
                            key = (seen_u or c == u, False, 0)
                        nxt[key] = (nxt.get(key, 0) + ways) % MOD
                states = nxt
                tail[length] = sum(
                    ways for (_, done, mask), ways in states.items()
                    if done and mask == fullmask
                ) % MOD

        answer = 0
        for q in range(N):
            # q positions precede the final w, then one w, then N-q-1 suffix.
            answer += pref[q] * tail[N - q - 1]
        return answer % MOD

    if comb(N, M) < K ** M - 1:
        return 0

    universe = K ** M
    if K ** N <= 700_000 and universe <= 20:
        x_code = 0
        for a in X:
            x_code = x_code * K + (a - 1)
        target = ((1 << universe) - 1) ^ (1 << x_code)
        total = 0
        for word in product(range(K), repeat=N):
            layers = [set() for _ in range(M + 1)]
            layers[0].add(())
            found = 0
            for a in word:
                for length in range(M - 1, -1, -1):
                    for prefix in tuple(layers[length]):
                        if length + 1 == M:
                            code = 0
                            for c in prefix + (a,):
                                code = code * K + c
                            found |= 1 << code
                        else:
                            layers[length + 1].add(prefix + (a,))
            if found == target:
                total += 1
        return total % MOD

    if M == 2 and K == 2:
        x_code = (X[0] - 1) * 2 + X[1] - 1
        target = 15 ^ (1 << x_code)
        states = {(0, 0, 0): 1}
        for _ in range(N):
            nxt = {}
            for (c0, c1, mask), ways in states.items():
                counts = (c0, c1)
                for a in range(2):
                    nm = mask
                    for b in range(2):
                        if counts[b]:
                            nm |= 1 << (2 * b + a)
                    nc = list(counts)
                    nc[a] = min(2, nc[a] + 1)
                    key = (nc[0], nc[1], nm)
                    nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(v for (c0, c1, mask), v in states.items() if mask == target) % MOD
    return 0

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n, decide whether an n by n binary matrix can have exactly k fixed cells.

    Two matrices are similar when their row sums and column sums agree. A cell
    is fixed when every binary matrix with those same margins has the same value
    in that cell.
    """
    if not isinstance(n, int) or not isinstance(k, int):
        return False
    if not 2 <= n <= 30 or not 0 <= k <= n * n:
        return False

    # Variable cells can be grouped into independent flexible blocks. A block
    # with a rows and b columns contributes a*b variable cells; both dimensions
    # must be at least two. The remaining cells can be fixed.
    #
    # possible[r][c] is a bitset whose bit t says that variable area t can be
    # obtained with r rows and c columns allocated to flexible blocks.
    possible = [[0] * (n + 1) for _ in range(n + 1)]
    possible[0][0] = 1

    # Unbounded knapsack over block dimensions.
    for a in range(2, n + 1):
        for b in range(2, n + 1):
            area = a * b
            for rows in range(a, n + 1):
                for cols in range(b, n + 1):
                    possible[rows][cols] |= possible[rows - a][cols - b] << area

    target = n * n - k
    target_bit = 1 << target
    return any(
        possible[rows][cols] & target_bit
        for rows in range(n + 1)
        for cols in range(n + 1)
    )

