from itertools import product
from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences whose only missing length-M subsequence is X."""
    if len(X) != M or any(v < 1 or v > K for v in X):
        return 0

    if M == 3 and K >= 3:
        u, v, w = (c - 1 for c in X)

        def surjections(length, alphabet_size):
            return sum((-1) ** j * comb(alphabet_size, j) *
                       pow(alphabet_size - j, length, MOD)
                       for j in range(alphabet_size + 1)) % MOD

        # Count prefixes containing all ordered pairs except (u,v).
        if u == v:
            # The omitted diagonal pair forces exactly one u. Every other
            # symbol must occur on both sides of it.
            d = K - 1
            one_side = [surjections(i, d) for i in range(N + 1)]
            prefix = [0] * (N + 1)
            for q in range(1, N + 1):
                prefix[q] = sum(one_side[left] * one_side[q - 1 - left]
                                for left in range(q)) % MOD
        else:
            # No u may precede v. The prefix therefore has a unique split
            # A v C u B. A and B contain all K-2 other symbols; A has >=2 v
            # and B has >=2 u to realize those diagonal pairs.
            d = K - 2

            def special_side(length):
                ans = 0
                for missing in range(d + 1):
                    s = d - missing
                    count = pow(s + 1, length, MOD) - pow(s, length, MOD)
                    if length:
                        count -= length * pow(s, length - 1, MOD)
                    ans += (-1) ** missing * comb(d, missing) * count
                return ans % MOD

            side = [special_side(i) for i in range(N + 1)]
            conv = [0] * (N + 1)
            for total in range(N + 1):
                val = 0
                for middle in range(total + 1):
                    left_total = total - middle
                    inner = sum(side[left] * side[left_total - left]
                                for left in range(left_total + 1))
                    val += pow(d, middle, MOD) * inner
                conv[total] = val % MOD
            prefix = [0] * (N + 1)
            for q in range(2, N + 1):
                prefix[q] = conv[q - 2]

        tail = [0] * (N + 1)
        if u == w and v != w:
            return 0
        if v == w:
            # The omitted pair completes at the final w; after it, every
            # symbol except w must still occur.
            for length in range(N + 1):
                tail[length] = surjections(length, K - 1)
        else:
            alphabet = [c for c in range(K) if c != w]
            idx = {c: i for i, c in enumerate(alphabet)}
            full = (1 << len(alphabet)) - 1
            states = {(False, 0): 1}  # before pair: u seen; after: suffix mask
            before_states = {(False, 0): 1}
            for length in range(1, N + 1):
                next_before = {}
                next_after = {}
                for (seen_u, _), ways in before_states.items():
                    for c in alphabet:
                        if c == v and seen_u:
                            key = (True, 0)  # trigger char is excluded from mask
                            next_after[key] = (next_after.get(key, 0) + ways) % MOD
                        else:
                            key = (seen_u or c == u, 0)
                            next_before[key] = (next_before.get(key, 0) + ways) % MOD
                for (unused, mask), ways in states.items():
                    for c in alphabet:
                        key = (True, mask | (1 << idx[c]))
                        next_after[key] = (next_after.get(key, 0) + ways) % MOD
                before_states = next_before
                states = next_after
                tail[length] = sum(ways for (_, mask), ways in states.items()
                                   if mask == full) % MOD

        return sum(prefix[q] * tail[N - q - 1] for q in range(N)) % MOD

    if comb(N, M) < K ** M - 1:
        return 0
    universe = K ** M
    if K ** N <= 700_000 and universe <= 20:
        xcode = 0
        for a in X:
            xcode = xcode * K + (a - 1)
        target = ((1 << universe) - 1) ^ (1 << xcode)
        total = 0
        for word in product(range(K), repeat=N):
            layers = [set() for _ in range(M + 1)]
            layers[0].add(())
            found = 0
            for a in word:
                for length in range(M - 1, -1, -1):
                    for prefix in tuple(layers[length]):
                        if length + 1 == M:
                            code = 0
                            for c in prefix + (a,):
                                code = code * K + c
                            found |= 1 << code
                        else:
                            layers[length + 1].add(prefix + (a,))
            if found == target:
                total += 1
        return total % MOD

    if M == 2 and K == 2:
        xcode = (X[0] - 1) * 2 + X[1] - 1
        target = 15 ^ (1 << xcode)
        states = {(0, 0, 0): 1}
        for _ in range(N):
            nxt = {}
            for (c0, c1, mask), ways in states.items():
                counts = (c0, c1)
                for a in range(2):
                    nm = mask
                    for b in range(2):
                        if counts[b]:
                            nm |= 1 << (2 * b + a)
                    nc = list(counts)
                    nc[a] = min(2, nc[a] + 1)
                    key = (nc[0], nc[1], nm)
                    nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(v for (_, _, mask), v in states.items() if mask == target) % MOD
    return 0

