        code = (X[0] - 1) * 2 + X[1] - 1
        target = 15 ^ (1 << code)
        states = {(0, 0, 0): 1}
        for _ in range(N):
            nxt = {}
            for (c0, c1, mask), ways in states.items():
                counts = (c0, c1)
                for a in range(2):
                    nm = mask
                    for b in range(2):
                        if counts[b]:
                            nm |= 1 << (2 * b + a)
                    nc = list(counts)
                    nc[a] = min(2, nc[a] + 1)
