from math import isqrt


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square numbers whose n-digit zero-padded digits match s."""
    target = [0] * 10
    for digit in s:
        target[ord(digit) - ord("0")] += 1

    last_root = isqrt(10 ** n - 1)
    found = 0

    # For n >= 2, only inspect roots whose square's final two digits can
    # occur in s and whose residue modulo 900 is itself a square residue.
    # Since 900 is divisible by 100, this filters by the exact two-digit
    # suffix; divisibility by 9 also supplies a cheap digit-sum constraint.
    if n >= 2:
        square_residues = {value * value % 900 for value in range(900)}
        allowed_residues = set()
        for residue in square_residues:
            suffix = residue % 100
            first = suffix // 10
            second = suffix % 10
            needed = [0] * 10
            needed[first] += 1
            needed[second] += 1
            if all(needed[digit] <= target[digit] for digit in range(10)):
                allowed_residues.add(residue)

        for root in range(last_root + 1):
            square = root * root
            if square % 900 not in allowed_residues:
                continue

            digits = str(square)
            frequencies = [0] * 10
            for digit in digits:
                frequencies[ord(digit) - ord("0")] += 1
            frequencies[0] += n - len(digits)
            if frequencies == target:
                found += 1
    else:
        for root in range(last_root + 1):
            square = root * root
            digits = str(square)
            frequencies = [0] * 10
            for digit in digits:
                frequencies[ord(digit) - ord("0")] += 1
            frequencies[0] += n - len(digits)
            if frequencies == target:
                found += 1

    return found

