from math import isqrt


_DIGIT_MASKS = tuple(1 << (4 * digit) for digit in range(10))
_ASCII_DIGIT_MASKS = tuple(
    _DIGIT_MASKS[code - 48] if 48 <= code <= 57 else 0
    for code in range(128)
)
_ZERO_MASK = _DIGIT_MASKS[0]


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square numbers whose n-digit zero-padded digits match s."""
    target = 0
    for digit in s:
        target += _DIGIT_MASKS[ord(digit) - 48]

    last_root = isqrt(10 ** n - 1)
    if n < 2:
        roots = range(last_root + 1)
    else:
        # A square's residue modulo 900 determines its two-digit suffix
        # and its residue modulo 9. Keep only suffixes available in s.
        square_residues = {value * value % 900 for value in range(900)}
        allowed = set()
        for residue in square_residues:
            suffix = residue % 100
            first, second = divmod(suffix, 10)
            needed = [0] * 10
            needed[first] += 1
            needed[second] += 1
            if all(needed[digit] <= s.count(str(digit)) for digit in range(10)):
                allowed.add(residue)

        root_classes = [
            residue
            for residue in range(900)
            if residue * residue % 900 in allowed
        ]
        count = 0
        for base in root_classes:
            for root in range(base, last_root + 1, 900):
                square = root * root
                digits = str(square)
                signature = (n - len(digits)) * _ZERO_MASK
                for character in digits:
