                remaining = length - pos
                if digit_sum > target_sum or digit_sum + 9 * remaining < target_sum:
                    return 0
                if pos == length:
                    return int(digit_sum == target_sum and product_mod == 0)

                bound_digit = bound[pos]
                upper = bound_digit if tight else 9
                upper = min(upper, target_sum - digit_sum)
