from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def strip(i, j, x, y):
        return y % K if (i + j) % 2 == 0 else x % K

    sk = strip(si, sj, S_x, S_y)
    tk = strip(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if dx + dy > 10000:
        delta = max(abs(T_x - S_x), abs(T_y - S_y))
        return (2 * delta + K - 1) // K

    strips = sorted({0, K - 1, sk, tk})
    imin, imax = min(si, ti) - 10, max(si, ti) + 10
    jmin, jmax = min(sj, tj) - 10, max(sj, tj) + 10

    def neighbors(state):
        i, j, k = state
        horizontal = (i + j) % 2 == 0
        for q in strips:
            if q != k:
                yield (i, j, q), abs(q - k)
        if horizontal:
            if i > imin:
                yield (i - 1, j, K - 1), 1
            if i < imax:
                yield (i + 1, j, 0), 1
            if k == 0 and j > jmin:
                for q in strips:
                    yield (i, j - 1, q), 1
            if k == K - 1 and j < jmax:
                for q in strips:
                    yield (i, j + 1, q), 1
        else:
            if j > jmin:
                yield (i, j - 1, K - 1), 1
            if j < jmax:
                yield (i, j + 1, 0), 1
            if k == 0 and i > imin:
                for q in strips:
                    yield (i - 1, j, q), 1
            if k == K - 1 and i < imax:
                for q in strips:
                    yield (i + 1, j, q), 1

    start, goal = (si, sj, sk), (ti, tj, tk)
    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, state = heappop(queue)
        if distance != distances[state]:
            continue
        if state == goal:
            return distance
        for nxt, cost in neighbors(state):
            candidate = distance + cost
            if candidate < distances.get(nxt, 10**30):
                distances[nxt] = candidate
                heappush(queue, (candidate, nxt))
    delta = max(abs(T_x - S_x), abs(T_y - S_y))
    return (2 * delta + K - 1) // K

